import {DAY,clock,split,progress,validateState,validateGoal,localInput,parseLocal,newState} from './domain.mjs';
import {TelegramCloudStore,CloudConflict,CloudUncertain} from './cloud.mjs';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(),tg=window.Telegram?.WebApp;
const categories={work:['Работа','↗'],health:['Здоровье','♡'],learning:['Развитие','✧'],personal:['Личное','◈']};
const fullDate=ms=>new Date(ms).toLocaleString('ru-RU',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const shortDate=ms=>new Date(ms).toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const dayKey=ms=>{const d=new Date(ms);return [d.getFullYear(),d.getMonth()+1,d.getDate()].join('-');};
let state=newState(),page='goals',filter='active',query='',selected=null,demo=false,realState=null,storageError=false,revision=null,cloud=null,cloudBlocked='',busy=false,clockOffset=0;
let storageKey='vector:v1:browser',toastTimer,baseRaw=null,corrupt=false;
const now=()=>Date.now()+clockOffset;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function load(){try{const raw=localStorage.getItem(storageKey);baseRaw=raw;if(raw)state=validateState(JSON.parse(raw));}catch{storageError=true;corrupt=baseRaw!==null;}}
function save(){if(demo)return true;if(corrupt){notify('Повреждённые данные защищены от перезаписи. Восстановите копию через настройки.');return false;}try{const current=localStorage.getItem(storageKey);if(current!==baseRaw){notify('Данные изменены в другой вкладке. Обновите страницу.');return false;}const raw=JSON.stringify(state);localStorage.setItem(storageKey,raw);baseRaw=raw;storageError=false;return true;}catch{storageError=true;notify('Не удалось сохранить. Экспортируйте резервную копию.');return false;}}
async function mutate(fn){if(busy)return;busy=true;document.body.classList.add('saving');const previous=structuredClone(state),previousCorrupt=corrupt;try{if(cloudBlocked&&!demo)throw Error(cloudBlocked);fn();validateState(state);if(cloud&&!demo){const saved=await cloud.write(state,revision);revision=saved.revision;}else if(!save()&&!demo)throw Error('Изменения не сохранены. Проверьте доступ к хранилищу.');render();if(selected&&$('#modal').open)showDetail(selected);return true;}catch(e){corrupt=previousCorrupt;state=previous;if(e instanceof CloudConflict){try{const latest=await cloud.load();state=latest.state;revision=latest.revision;}catch{cloudBlocked='Не удалось загрузить облако. Заново откройте приложение.';}}if(e instanceof CloudUncertain)cloudBlocked=e.message;notify(e.message);render();if(selected&&$('#modal').open)showDetail(selected);return false;}finally{busy=false;document.body.classList.remove('saving');}}
function event(text,goalId){state.events.unshift({id:uid(),at:now(),text,goalId});state.events=state.events.slice(0,5000);}
function badge(g){const c=clock(g,now());return g.completedAt?'<span class="badge">✓ Завершена</span>':c.scheduled?'<span class="badge gray">◷ Запланирована</span>':c.overdue?'<span class="badge orange">Дедлайн прошёл</span>':'<span class="badge">● В процессе</span>';}
function digits(ms){return '<div class="digits">'+split(ms).map((v,i)=>`${i?'<div class="colon">:</div>':''}<div class="digit"><strong>${String(v).padStart(2,'0')}</strong><span>${['ДНЕЙ','ЧАСОВ','МИНУТ','СЕКУНД'][i]}</span></div>`).join('')+'</div>';}
function timers(){document.querySelectorAll('[data-clock]').forEach(el=>{const g=state.goals.find(g=>g.id===el.dataset.clock);if(g)el.innerHTML=digits(el.dataset.kind==='remainingStart'?g.startAt-now():clock(g,now())[el.dataset.kind||'elapsed']);});document.querySelectorAll('[data-days]').forEach(el=>{const g=state.goals.find(g=>g.id===el.dataset.days);if(!g)return;const c=clock(g,now());el.textContent=g.completedAt?'Цель завершена':c.overdue?'Дедлайн прошёл':`${c.daysLeft} дн. до дедлайна`;});$('#wall-clock').textContent=new Date(now()).toLocaleTimeString('ru-RU')+' · '+Intl.DateTimeFormat().resolvedOptions().timeZone;}
function overview(){const active=state.goals.filter(g=>!g.completedAt),done=state.goals.filter(g=>g.completedAt),actions=state.goals.flatMap(g=>g.actions).filter(a=>a.doneAt);return `<div class="overview"><article><div class="stat-label">Активные цели</div><span class="stat-icon">↗</span><div class="stat-value">${active.length}<small>в твоём фокусе</small></div></article><article><div class="stat-label">Завершённые цели</div><span class="stat-icon">✓</span><div class="stat-value">${done.length}<small>поводов гордиться</small></div></article><article><div class="stat-label">Выполненные действия</div><span class="stat-icon">✧</span><div class="stat-value">${actions.length}<small>шагов вперёд</small></div></article></div>`;}
function top(title,sub,button=true){return `<div class="page-top"><div><div class="eyebrow">КАЖДЫЙ ШАГ ИМЕЕТ ЗНАЧЕНИЕ</div><h1>${title}</h1><p class="sub">${sub}</p></div>${button?'<button class="primary" data-do="create"><span class="plus">＋</span> Новая цель</button>':''}</div>`;}
function card(g,featured){const p=progress(g),c=clock(g,now()),[cat,icon]=categories[g.category];return `<article class="goal-card ${featured?'featured':''}" tabindex="0" role="button" aria-label="Открыть цель ${esc(g.title)}" data-open="${g.id}"><div class="card-top"><div class="category"><span class="category-icon">${icon}</span>${cat}${featured?' <span> / В ФОКУСЕ</span>':''}</div>${badge(g)}</div><div class="${featured?'featured-body':''}"><div><h2>${esc(g.title)}</h2><p class="description">${esc(g.description||'Твоя следующая большая перемена')}</p><div class="time-caption">${c.scheduled?'ДО НАЧАЛА':'ВРЕМЯ С НАЧАЛА ЦЕЛИ'}</div><div data-clock="${g.id}" data-kind="${c.scheduled?'remainingStart':'elapsed'}">${digits(c.scheduled?g.startAt-now():c.elapsed)}</div></div>${featured?`<div class="ring" style="--p:${p}"><div class="ring-inner"><strong>${p}%</strong><span>твоего пути</span></div></div>`:''}</div><div class="progress-row"><span>${g.actions.filter(a=>a.doneAt).length} из ${g.actions.length} действий</span><strong>${p}% выполнено</strong></div><div class="progress-track"><i style="width:${p}%"></i></div><div class="card-bottom"><span>◷ Дедлайн <strong>${shortDate(g.deadlineAt)}</strong></span><span data-days="${g.id}" class="${c.overdue?'urgent':''}">${c.overdue?'Дедлайн прошёл':c.daysLeft+' дн. до дедлайна'}</span><span>↗</span></div></article>`;}
function eventsHTML(events){return events.length?`<div class="activity">${events.map(e=>`<div class="event"><span class="event-dot">✓</span><span class="event-text">${esc(e.text)}</span><time datetime="${new Date(e.at).toISOString()}">${dayKey(e.at)===dayKey(now())?new Date(e.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):shortDate(e.at)}</time></div>`).join('')}</div>`:'<div class="empty"><div class="empty-symbol">◷</div><h2>История начинается с тебя</h2><p>Создавай цели и отмечай действия. Здесь сохранится твой путь.</p></div>';}
function goalsPage(){const active=state.goals.filter(g=>!g.completedAt).length,done=state.goals.length-active;let list=state.goals.filter(g=>(filter==='all'||filter==='active'&&!g.completedAt||filter==='done'&&g.completedAt)&&`${g.title} ${g.description}`.toLowerCase().includes(query.toLowerCase()));list.sort((a,b)=>Number(!!a.completedAt)-Number(!!b.completedAt)||a.deadlineAt-b.deadlineAt);return top('Твой следующий уровень.','Меньше суеты. Больше движения к тому, что важно.')+overview()+(!state.goals.length?`<div class="welcome"><div class="eyebrow">ТОЧКА ОТСЧЁТА</div><h2>У каждой большой цели<br>есть первый шаг.</h2><p>Задай направление, выбери срок и разбей путь на простые действия. Вектор поможет видеть, как ты продвигаешься.</p><div class="welcome-buttons"><button class="primary" data-do="create">＋ Создать первую цель</button><button class="ghost" data-do="demo">Посмотреть пример ↗</button></div></div>`:`<div class="toolbar"><div class="tabs">${[['active','Активные',active],['done','Завершённые',done],['all','Все цели',state.goals.length]].map(([id,label,n])=>`<button data-filter="${id}" class="${filter===id?'selected':''}">${label}<small>${n}</small></button>`).join('')}</div><input type="search" class="search" id="search" placeholder="⌕  Найти свою цель" aria-label="Поиск целей" value="${esc(query)}"></div><div class="goals-grid">${list.length?list.map((g,i)=>card(g,i===0&&filter!=='done')).join(''):'<div class="empty"><div class="empty-symbol">◈</div><h2>Здесь пока тихо</h2><p>Нет целей, подходящих под выбранный фильтр.</p><button class="ghost" data-do="reset-filter">Показать все цели</button></div>'}</div>`)+`<div class="section-title"><h2>Последние шаги</h2><button class="text-button" data-page="history">Вся история ↗</button></div>`+eventsHTML(state.events.slice(0,3));}
function statsPage(){const days=Array.from({length:7},(_,i)=>{const d=new Date(now());d.setDate(d.getDate()-6+i);return {date:d,n:state.goals.flatMap(g=>g.actions).filter(a=>a.doneAt&&dayKey(a.doneAt)===dayKey(d)).length};});const max=Math.max(1,...days.map(d=>d.n));return top('Видеть свой прогресс.','Каждое выполненное действие — уже результат.',false)+overview()+`<div class="stats-grid"><section class="settings-panel"><h2>Твоя активность</h2><p>Выполненные действия за последние 7 дней</p><div class="chart">${days.map(d=>`<div class="bar-col"><b>${d.n}</b><div class="bar" style="height:${Math.max(2,d.n/max*110)}px"></div><small>${d.date.toLocaleDateString('ru-RU',{weekday:'short'})} ${d.date.getDate()}</small></div>`).join('')}</div></section><section class="settings-panel"><h2>Направления роста</h2><p>Средний прогресс действий в каждой сфере</p>${Object.entries(categories).map(([k,[label]])=>{const gs=state.goals.filter(g=>g.category===k),p=gs.length?Math.round(gs.reduce((a,g)=>a+progress(g),0)/gs.length):0;return `<div class="category-stat"><span>${label}</span><div class="progress-track"><i style="width:${p}%"></i></div><b>${p}%</b></div>`;}).join('')}</section></div><section class="settings-panel"><h2>Честные цифры</h2><p>Прогресс считается по выполненным действиям, а не по прошедшему времени. Завершённые цели и действия учитываются, пока цель хранится в приложении. История сохраняет последние 5000 событий. Дни активности определяются в часовом поясе этого устройства.</p></section>`;}
function settingsPage(){return top('Твоё пространство.','Всё важное — под твоим контролем.',false)+`<section class="settings-panel"><h2>Хранение данных</h2><p>${cloud?'Цели и история сохраняются в Telegram CloudStorage для вашего аккаунта и этого бота. Они загружаются на других устройствах при открытии приложения. Не редактируйте одну цель одновременно на нескольких устройствах.':'Автономный режим: цели хранятся в этом браузере на этом устройстве. При очистке данных браузера они могут быть удалены. Делайте резервные копии. Между устройствами данные сейчас не синхронизируются.'}</p><div class="settings-actions"><button class="primary" data-do="export">Экспорт данных ↓</button><button class="ghost" data-do="import">Импорт копии ↑</button></div><input type="file" id="import-file" accept="application/json,.json" hidden></section><section class="settings-panel"><h2>Время и точность</h2><p>Часовой пояс: <b>${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</b>. Даты хранятся как абсолютное время UTC, показываются в часовом поясе устройства. Часы продолжают идти при закрытом приложении. ${'Точность часов зависит от системного времени устройства. Telegram CloudStorage хранит данные, но не предоставляет источник точного времени.'}</p><p>Дедлайн — календарный срок. Таймер — выбранная длительность от начала цели. Они независимы. Завершение фиксирует итоговое прошедшее время; таймер сам не завершает цель.</p></section><section class="settings-panel"><h2>Исследуй возможности</h2><p>Открой пример с целями и действиями. Твои данные будут сохранены отдельно и вернутся после выхода из примера.</p><button class="ghost" data-do="demo">${demo?'Выйти из примера':'Открыть пример'} ↗</button></section><section class="settings-panel"><h2>О приложении</h2><p>Вектор · Версия 2.0 · Telegram Cloud<br>Собственный темп. Осознанные действия. Настоящий прогресс.</p></section>`;}
function render(){const labels={goals:'Мои цели',stats:'Статистика',history:'История',settings:'Настройки'};$('#page-label').textContent=labels[page];$('#nav-count').textContent=state.goals.filter(g=>!g.completedAt).length;document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#mode').textContent=demo?'Пример · данные не сохраняются':cloudBlocked?'Облако недоступно':cloud?'Облако Telegram':'На этом устройстве';$('#content').innerHTML=(demo?'<div class="demo-note" style="margin-top:18px">Режим примера. <button class="text-button" data-do="demo">Вернуться к моим данным ↗</button></div>':'')+(cloudBlocked?'<div class="storage-warning" style="margin-top:18px">'+esc(cloudBlocked)+' Цели в облаке защищены от перезаписи. Закройте и заново откройте Mini App для повторной загрузки.</div>':'')+(storageError?'<div class="storage-warning" style="margin-top:18px">Хранилище недоступно или повреждено. Исходные данные не перезаписаны. Экспортируйте доступные данные; попробуйте перезапустить приложение.</div>':'')+(page==='goals'?goalsPage():page==='stats'?statsPage():page==='settings'?settingsPage():top('Твой путь в деталях.','Маленькие победы, которые складываются в большую историю.',false)+eventsHTML(state.events));timers();}
function openModal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();tg?.BackButton?.show();}
function closeModal(){selected=null;$('#modal').close();tg?.BackButton?.hide();}
function formGoal(id){selected=null;const g=state.goals.find(g=>g.id===id),start=g?.startAt??now(),end=g?.deadlineAt??start+30*DAY;openModal(`<div class="modal-head"><h2>${g?'Настроить цель':'Новое направление'}</h2><button class="close" data-do="close" aria-label="Закрыть">×</button></div><form id="goal-form" data-id="${g?.id||''}"><label for="title">Какую цель ты хочешь достичь?</label><input id="title" name="title" required maxlength="100" placeholder="Например, пробежать свои первые 10 км" value="${esc(g?.title||'')}"><label for="description">Почему это важно для тебя?</label><textarea id="description" name="description" maxlength="2000" placeholder="Опиши желаемый результат…">${esc(g?.description||'')}</textarea><label for="category">Направление</label><select id="category" name="category">${Object.entries(categories).map(([id,[label]])=>`<option value="${id}" ${g?.category===id?'selected':''}>${label}</option>`).join('')}</select><div class="form-grid"><div><label for="start">Дата и время начала</label><input type="datetime-local" id="start" name="start" required value="${localInput(start)}"></div><div><label for="deadline">Дедлайн</label><input type="datetime-local" id="deadline" name="deadline" required value="${localInput(end)}"></div></div><div class="form-grid"><div><label for="duration">Длительность таймера</label><input type="number" name="duration" id="duration" min="1" max="5256000" step="1" value="${g?Math.round(g.durationMs/60000):30}" required></div><div><label for="unit">Единица времени</label><select name="unit" id="unit"><option value="60000">Минуты</option><option value="3600000">Часы</option><option value="86400000" ${g?'':'selected'}>Дни</option></select></div></div><p class="hint">${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)} · Таймер идёт от начала цели, независимо от дедлайна. Действия можно добавить после создания.</p><div id="form-error" class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="ghost" data-do="close">Отмена</button><button class="primary" type="submit">${g?'Сохранить изменения':'Создать цель ↗'}</button></div></form>`);}
function showDetail(id){const g=state.goals.find(g=>g.id===id);if(!g){closeModal();return;}selected=id;const c=clock(g,now());openModal(`<div class="modal-head"><h2>${esc(g.title)}</h2><button class="close" data-do="close" aria-label="Закрыть">×</button></div>${badge(g)}<p class="detail-desc">${esc(g.description)}</p><div class="time-caption">${c.scheduled?'ДО НАЧАЛА ЦЕЛИ':'ПРОШЛО С НАЧАЛА'}</div><div class="detail-clock" data-clock="${g.id}" data-kind="${c.scheduled?'remainingStart':'elapsed'}">${digits(c.scheduled?g.startAt-now():c.elapsed)}</div><div class="detail-meta"><article><small>НАЧАЛО</small><b>${fullDate(g.startAt)}</b></article><article><small>ДЕДЛАЙН</small><b>${fullDate(g.deadlineAt)}</b></article><article><small>ДО ДЕДЛАЙНА</small><b data-clock-text="deadline">${split(c.remaining).map((n,i)=>n+['д ','ч ','м ','с'][i]).join('')}</b></article><article><small>ТАЙМЕР · ОСТАЛОСЬ</small><b data-clock-text="timer">${c.scheduled?'Ожидает начала':c.timerExpired?'Время вышло':split(c.timerRemaining).map((n,i)=>n+['д ','ч ','м ','с'][i]).join('')}</b></article></div><div class="progress-row"><span>Прогресс по действиям</span><strong>${progress(g)}%</strong></div><div class="progress-track"><i style="width:${progress(g)}%"></i></div><div class="section-title"><h2>Шаги к цели</h2><span class="sub">${g.actions.filter(a=>a.doneAt).length} / ${g.actions.length}</span></div>${g.actions.length?g.actions.map(a=>`<div class="action-row ${a.doneAt?'done':''}"><button class="check ${a.doneAt?'checked':''}" data-toggle="${a.id}" aria-label="${a.doneAt?'Отменить':'Выполнить'}: ${esc(a.title)}" aria-pressed="${!!a.doneAt}" ${g.completedAt?'disabled':''}>${a.doneAt?'✓':''}</button><span>${esc(a.title)}</span><button class="delete-action" data-remove-action="${a.id}" aria-label="Удалить действие" ${g.completedAt?'disabled':''}>×</button></div>`).join(''):'<p class="hint">Разбей большую цель на понятные шаги.</p>'}${!g.completedAt?'<form id="action-form" class="add-action"><input name="action" aria-label="Новое действие" placeholder="Добавить следующий шаг…" required maxlength="200"><button class="secondary" aria-label="Добавить действие">＋</button></form>':''}<div class="detail-footer"><button class="text-button" data-delete="${id}">Удалить цель</button><div class="settings-actions"><button class="ghost" data-edit="${id}">Изменить</button><button class="primary" data-complete="${id}" ${c.scheduled?'disabled':''}>${g.completedAt?'Открыть снова':'✓ Завершить'}</button></div></div>`);}
function detailTick(){if(!selected||!$('#modal').open)return;const g=state.goals.find(g=>g.id===selected);if(!g)return;const c=clock(g,now());const d=$('[data-clock-text="deadline"]'),t=$('[data-clock-text="timer"]');if(d)d.textContent=c.overdue?'Дедлайн прошёл':split(c.remaining).map((n,i)=>n+['д ','ч ','м ','с'][i]).join('');if(t)t.textContent=c.scheduled?'Ожидает начала':c.timerExpired?'Время вышло':split(c.timerRemaining).map((n,i)=>n+['д ','ч ','м ','с'][i]).join('');}
function demoToggle(){if(demo){state=realState;realState=null;demo=false;}else{realState=state;demo=true;const n=now();state=newState();const make=(title,description,category,days,total,titles,done)=>({id:uid(),title,description,category,startAt:n-days*DAY-3*3600000-24*60000,deadlineAt:n+total*DAY,durationMs:60*DAY,createdAt:n-days*DAY,updatedAt:n,completedAt:null,actions:titles.map((title,i)=>({id:uid(),title,doneAt:i<done?n-i*DAY:null}))});state.goals=[make('Пробежать свои первые 10 км','Стать выносливее и почувствовать, на что я способен.','health',12,18,['Купить удобные кроссовки','Составить план тренировок','Пробежать 3 км','Пробежать 5 км','Пробежать 7 км','Финишировать на 10 км'],3),make('Английский — новый уровень','30 минут каждый день, чтобы говорить свободнее.','learning',8,42,['Пройти тест уровня','Выбрать учебник','Выучить 100 слов','Посмотреть фильм','Пройти курс'],2),make('Запустить свой проект','Превратить идею в то, чем можно гордиться.','work',5,25,['Исследование','Прототип','Разработка','Первый клиент'],1)];state.events=state.goals.flatMap(g=>g.actions.filter(a=>a.doneAt).map(a=>({id:uid(),at:a.doneAt,text:`${a.title} · ${g.title}`,goalId:g.id}))).sort((a,b)=>b.at-a.at);}filter='active';query='';page='goals';closeModal();render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-open]');if(!b||b.disabled||busy)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo({top:0});return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.open){showDetail(b.dataset.open);return;}if(b.dataset.edit){formGoal(b.dataset.edit);return;}if(b.dataset.toggle){const id=selected;await mutate(()=>{const g=state.goals.find(g=>g.id===id),a=g.actions.find(a=>a.id===b.dataset.toggle);a.doneAt=a.doneAt?null:now();g.updatedAt=now();event(`${a.doneAt?'Выполнено':'Отменено'}: ${a.title} · ${g.title}`,g.id);});tg?.HapticFeedback?.impactOccurred('light');return;}if(b.dataset.removeAction){await mutate(()=>{const g=state.goals.find(g=>g.id===selected),a=g.actions.find(a=>a.id===b.dataset.removeAction);g.actions=g.actions.filter(a=>a.id!==b.dataset.removeAction);g.updatedAt=now();event(`Удалено действие: ${a.title}`,g.id);});return;}if(b.dataset.complete){const g=state.goals.find(g=>g.id===b.dataset.complete);if(!g.completedAt&&g.actions.some(a=>!a.doneAt)){openModal(`<div class="modal-head"><h2>Завершить цель?</h2><button class="close" data-do="close">×</button></div><p class="detail-desc">Остались невыполненные действия. Можно завершить цель сейчас — их статус сохранится.</p><div class="modal-actions"><button class="ghost" data-open="${g.id}">Вернуться</button><button class="primary" data-force-complete="${g.id}">Завершить</button></div>`);return;}await complete(g.id);return;}if(b.dataset.forceComplete){await complete(b.dataset.forceComplete);return;}if(b.dataset.delete){const g=state.goals.find(g=>g.id===b.dataset.delete);openModal(`<div class="modal-head"><h2>Удалить цель?</h2><button class="close" data-do="close">×</button></div><p class="detail-desc">«${esc(g.title)}» и её действия будут удалены. Это нельзя отменить. История событий останется.</p><div class="modal-actions"><button class="ghost" data-open="${g.id}">Отмена</button><button class="danger" data-confirm-delete="${g.id}">Удалить цель</button></div>`);return;}if(b.dataset.confirmDelete){const id=b.dataset.confirmDelete;const ok=await mutate(()=>{const g=state.goals.find(g=>g.id===id);event(`Удалена цель: ${g.title}`,g.id);state.goals=state.goals.filter(g=>g.id!==id);});if(ok){closeModal();notify('Цель удалена');}return;}switch(b.dataset.do){case'create':formGoal();break;case'close':closeModal();break;case'reset-filter':filter='all';query='';render();break;case'demo':demoToggle();break;case'export':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'}));a.href=url;a.download='vector-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Резервная копия подготовлена');break;}case'import':$('#import-file').click();break;}});
async function complete(id){const ok=await mutate(()=>{const g=state.goals.find(g=>g.id===id);g.completedAt=g.completedAt?null:now();g.updatedAt=now();event(`${g.completedAt?'Завершена':'Снова открыта'} цель: ${g.title}`,id);});if(ok)notify('Статус цели обновлён');}
document.addEventListener('submit',async e=>{if(e.target.id==='goal-form'){e.preventDefault();const form=e.target,data=new FormData(form),existing=state.goals.find(g=>g.id===form.dataset.id);try{const n=now(),g={id:existing?.id||uid(),title:data.get('title').trim(),description:data.get('description').trim(),category:data.get('category'),startAt:parseLocal(data.get('start')),deadlineAt:parseLocal(data.get('deadline')),durationMs:Number(data.get('duration'))*Number(data.get('unit')),createdAt:existing?.createdAt||n,updatedAt:n,completedAt:existing?.completedAt||null,actions:existing?.actions||[]};validateGoal(g);if(state.goals.length>=300&&!existing)throw Error('Можно хранить не более 300 целей.');const ok=await mutate(()=>{if(existing)state.goals[state.goals.findIndex(x=>x.id===g.id)]=g;else state.goals.unshift(g);event(`${existing?'Обновлена':'Создана'} цель: ${g.title}`,g.id);});if(ok){showDetail(g.id);notify(existing?'Изменения сохранены':'Направление задано. Первый шаг за тобой!');}}catch(err){$('#form-error').textContent=err.message;}}if(e.target.id==='action-form'){e.preventDefault();const title=new FormData(e.target).get('action').trim();if(!title)return;await mutate(()=>{const g=state.goals.find(g=>g.id===selected);g.actions.push({id:uid(),title,doneAt:null});g.updatedAt=now();event(`Добавлено действие: ${title} · ${g.title}`,g.id);});}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange?.(pos,pos);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open][role="button"]')){e.preventDefault();showDetail(e.target.dataset.open);}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>3e6)throw Error('Файл слишком большой (максимум 3 МБ)');const imported=validateState(JSON.parse(await file.text()));openModal(`<div class="modal-head"><h2>Восстановить копию?</h2><button class="close" data-do="close">×</button></div><p class="detail-desc">В копии ${imported.goals.length} целей. Текущие цели и история будут заменены. Сначала экспортируйте текущие данные, если хотите сохранить их.</p><div class="modal-actions"><button class="ghost" data-do="close">Отмена</button><button id="confirm-import" class="primary">Восстановить</button></div>`);$('#confirm-import').onclick=async()=>{const ok=await mutate(()=>{state=imported;corrupt=false;event('Восстановлена резервная копия',null);});if(ok){closeModal();notify('Копия восстановлена');}};}catch(err){notify('Не удалось импортировать: '+err.message);}e.target.value='';});
$('#modal').addEventListener('cancel',()=>{selected=null;tg?.BackButton?.hide();});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('storage',e=>{if(e.key===storageKey&&!demo&&!cloud){try{state=e.newValue?validateState(JSON.parse(e.newValue)):newState();baseRaw=e.newValue;render();if(selected)showDetail(selected);notify('Данные обновлены из другой вкладки');}catch{notify('Не удалось обновить данные из другой вкладки');}}});
async function init(){try{if(tg){tg.ready();tg.expand();tg.setHeaderColor('#111410');tg.setBackgroundColor('#111410');const safe=()=>{document.documentElement.style.setProperty('--safe-top',Math.max(tg.safeAreaInset?.top||0,tg.contentSafeAreaInset?.top||0)+'px');document.documentElement.style.setProperty('--safe-bottom',Math.max(tg.safeAreaInset?.bottom||0,tg.contentSafeAreaInset?.bottom||0)+'px');};safe();tg.onEvent('safeAreaChanged',safe);tg.onEvent('contentSafeAreaChanged',safe);tg.BackButton.onClick(closeModal);}}catch{}
 if(tg?.initData){try{if(!tg.CloudStorage||!tg.isVersionAtLeast('6.9'))throw Error('Обновите Telegram для работы с облачным хранилищем.');cloud=new TelegramCloudStore(tg.CloudStorage);const data=await cloud.load();state=data.state;revision=data.revision;if(data.recovered)notify('Основная копия повреждена. Загружена предыдущая облачная версия.');}catch(error){cloudBlocked=error.message;notify('Облако пока недоступно. Ваши данные не перезаписаны.');}}else load();render();}
$('#content').innerHTML='<div class="empty" style="margin-top:30px"><div class="empty-symbol">↗</div><h2>Находим твой вектор…</h2><p>Загружаем цели и сверяем время.</p></div>';
await init();let lastTick=now();setInterval(()=>{const n=now();if(state.goals.some(g=>!g.completedAt&&(g.startAt>lastTick&&g.startAt<=n||g.deadlineAt>=lastTick&&g.deadlineAt<n))){render();if(selected)showDetail(selected);}lastTick=n;timers();detailTick();},1000);
async function refreshCloud(){if(!cloud||busy||demo||$('#modal').open||cloudBlocked)return;busy=true;try{const latest=await cloud.load();if(latest.revision!==revision){state=latest.state;revision=latest.revision;render();notify('Цели обновлены из облака Telegram');}}catch{notify('Не удалось обновить облако. Проверьте соединение.');}finally{busy=false;}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){timers();detailTick();refreshCloud();}});
window.addEventListener('focus',refreshCloud);
